-- ============================================================
-- SEED DE DADOS PARA TESTE - CLÍNICA DENTAL ANNE
-- Execute este script no Supabase SQL Editor
-- ============================================================

-- 1. Políticas RLS permissivas (ambiente de desenvolvimento)
DO $$
BEGIN
  -- Clinics
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'clinics' AND policyname = 'dev_allow_all') THEN
    CREATE POLICY "dev_allow_all" ON clinics FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Professionals
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'professionals' AND policyname = 'dev_allow_all') THEN
    CREATE POLICY "dev_allow_all" ON professionals FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Insurance plans
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'insurance_plans' AND policyname = 'dev_allow_all') THEN
    CREATE POLICY "dev_allow_all" ON insurance_plans FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Patients
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'patients' AND policyname = 'dev_allow_all') THEN
    CREATE POLICY "dev_allow_all" ON patients FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Appointments
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'appointments' AND policyname = 'dev_allow_all') THEN
    CREATE POLICY "dev_allow_all" ON appointments FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Payments
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'payments' AND policyname = 'dev_allow_all') THEN
    CREATE POLICY "dev_allow_all" ON payments FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Expenses
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'expenses' AND policyname = 'dev_allow_all') THEN
    CREATE POLICY "dev_allow_all" ON expenses FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Prosthetics
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'prosthetics' AND policyname = 'dev_allow_all') THEN
    CREATE POLICY "dev_allow_all" ON prosthetics FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Inventory items
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'inventory_items' AND policyname = 'dev_allow_all') THEN
    CREATE POLICY "dev_allow_all" ON inventory_items FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Inventory movements
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'inventory_movements' AND policyname = 'dev_allow_all') THEN
    CREATE POLICY "dev_allow_all" ON inventory_movements FOR ALL USING (true) WITH CHECK (true);
  END IF;
END $$;

